pair C = dir(-20);
pair M = (B + C)/2;
pair D = intersectionpoint(A--C, Circle(C, 1));
pair E = intersectionpoint(A--B, Circle(B, 1));

draw(A--B--C--cycle);
draw(D--A--E);
draw(C--D);
draw(C--E);
markangle(Label("$120^\circ$",Relative(0.5)),B,C,D,marker(markinterval(stickframe(n=1),true),true));
draw(Circle(A,1));
label("$B$", B, N);
label("$C$", C, E);
label("$M$", M, NE);
label("$D$", D, NW);
label("$E$", E, W);
